import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readText())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    val x = IntArray(15)
    val y = IntArray(15)
    for (i in 1..n) {
        x[i] = st.nextToken().toInt()
        y[i] = st.nextToken().toInt()
    }

    val mod = 998244353

    val px = IntArray(1 shl 5)
    val py = IntArray(1 shl 5)
    val nx = IntArray(1 shl 5)
    val ny = IntArray(1 shl 5)

    for (i in 0 until (1 shl n)) {
        for (j in 1..n) {
            if ((i shr (j - 1)) and 1 == 1) {
                if (x[j] > 0) px[i] += Math.abs(x[j]) else nx[i] += Math.abs(x[j])
                if (y[j] > 0) py[i] += Math.abs(y[j]) else ny[i] += Math.abs(y[j])
            }
        }
    }

    val dp = Array(31) { Array(21) { Array(21) { Array(21) { Array(21) { Array(2) { IntArray(2) } } } } } }
    dp[0][0][0][0][0][0][0] = 1

    for (i in 0..29) {
        for (cpx in 0..19) for (cnx in 0..19) for (cpy in 0..19) for (cny in 0..19) {
            for (bx in 0..1) for (by in 0..1) {
                val cur = dp[i][cpx][cnx][cpy][cny][bx][by]
                if (cur != 0) {
                    for (msk in 0 until (1 shl n)) {
                        val npx = cpx + px[msk]
                        val npy = cpy + py[msk]
                        val nnx = cnx + nx[msk]
                        val nny = cny + ny[msk]
                        if ((npx and 1) != (nnx and 1)) continue
                        if ((npy and 1) != (nny and 1)) continue
                        val cx = npx and 1
                        val cy = npy and 1
                        val mx = (m shr i) and 1
                        val my = mx
                        val nbx = if (cx == mx) bx else if (cx > mx) 1 else 0
                        val nby = if (cy == my) by else if (cy > my) 1 else 0
                        var newVal = dp[i + 1][npx shr 1][nnx shr 1][npy shr 1][nny shr 1][nbx][nby] + cur
                        if (newVal >= mod) newVal -= mod
                        dp[i + 1][npx shr 1][nnx shr 1][npy shr 1][nny shr 1][nbx][nby] = newVal
                    }
                }
            }
        }
    }

    println((dp[30][0][0][0][0][0][0] + mod - 1) % mod)
}
